	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/login/email:start", wrapper.StartEmailLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/login/email:verify", wrapper.VerifyEmailLogin)
